This C++17 implementation preserves helpcross.in and helpcross.out.

```cpp
#include <algorithm>
#include <fstream>
#include <functional>
#include <queue>
#include <utility>
#include <vector>
int main() {
    std::ifstream in("helpcross.in");
    std::ofstream out("helpcross.out");
    int c, n;
    if (!(in >> c >> n)) return 1;
    std::vector<long long> chicken(c);
    std::vector<std::pair<long long, long long>> cow(n);
    for (auto &t : chicken) in >> t;
    for (auto &interval : cow) in >> interval.first >> interval.second;
    std::sort(chicken.begin(), chicken.end());
    std::sort(cow.begin(), cow.end());
    std::priority_queue<long long, std::vector<long long>, std::greater<long long>> deadline;
    int j = 0, answer = 0;
    for (long long t : chicken) {
        while (j < n && cow[j].first <= t) deadline.push(cow[j++].second);
        while (!deadline.empty() && deadline.top() < t) deadline.pop();
        if (!deadline.empty()) {
            deadline.pop();
            ++answer;
        }
    }
    out << answer << '\n';
}
