The following C++17 implementation uses maxcross.in and maxcross.out.

```cpp
#include <algorithm>
#include <fstream>
#include <vector>
int main() {
    std::ifstream in("maxcross.in");
    std::ofstream out("maxcross.out");
    int n, k, b;
    if (!(in >> n >> k >> b)) return 1;
    std::vector<int> broken(n + 1, 0), prefix(n + 1, 0);
    for (int i = 0; i < b; ++i) {
        int position;
        in >> position;
        broken[position] = 1;
    }
    for (int i = 1; i <= n; ++i) prefix[i] = prefix[i - 1] + broken[i];
    int best = k;
    for (int start = 0; start + k <= n; ++start)
        best = std::min(best, prefix[start + k] - prefix[start]);
    out << best << '\n';
}
