This C++17 implementation preserves countcross.in and countcross.out.

```cpp
#include <array>
#include <fstream>
#include <utility>
#include <vector>
int main() {
    std::ifstream in("countcross.in");
    std::ofstream out("countcross.out");
    int n, k;
    long long roadRecords;
    if (!(in >> n >> k >> roadRecords)) return 1;
    const std::array<int, 4> dr{-1, 0, 1, 0}, dc{0, 1, 0, -1};
    std::vector<std::vector<std::array<bool, 4>>> blocked(
        n + 1, std::vector<std::array<bool, 4>>(n + 1));
    for (long long i = 0; i < roadRecords; ++i) {
        int r, c, rr, cc;
        in >> r >> c >> rr >> cc;
        int direction = -1;
        for (int d = 0; d < 4; ++d)
            if (r + dr[d] == rr && c + dc[d] == cc) direction = d;
        if (direction < 0) return 1;
        blocked[r][c][direction] = true;
        blocked[rr][cc][(direction + 2) % 4] = true;
    }
    std::vector<std::vector<int>> component(n + 1, std::vector<int>(n + 1, -1));
    int groups = 0;
    for (int r = 1; r <= n; ++r) {
        for (int c = 1; c <= n; ++c) {
            if (component[r][c] >= 0) continue;
            std::vector<std::pair<int, int>> stack{{r, c}};
            component[r][c] = groups;
            while (!stack.empty()) {
                auto [x, y] = stack.back();
                stack.pop_back();
                for (int d = 0; d < 4; ++d) {
                    int xx = x + dr[d], yy = y + dc[d];
                    if (xx < 1 || xx > n || yy < 1 || yy > n || blocked[x][y][d]) continue;
                    if (component[xx][yy] < 0) {
                        component[xx][yy] = groups;
                        stack.emplace_back(xx, yy);
                    }
                }
            }
            ++groups;
        }
    }
    std::vector<long long> cows(groups, 0);
    for (int i = 0; i < k; ++i) {
        int r, c;
        in >> r >> c;
        ++cows[component[r][c]];
    }
    long long answer = 1LL * k * (k - 1) / 2;
    for (long long size : cows) answer -= size * (size - 1) / 2;
    out << answer << '\n';
}
